127:       KJ_SYSCALL(dup2(raiiOpen(filename, O_WRONLY | O_CREAT | O_TRUNC | O_CLOEXEC), STDOUT_FILENO));
128:     }
129: 
130:     // Use Andy's ridiculous pivot_root trick to place ourselves into the sandbox.
131:     // See supervisor-main.c++ for more discussion.
132:     {
133:       auto oldRootDir = raiiOpen("/", O_RDONLY | O_DIRECTORY | O_CLOEXEC);
134:       KJ_SYSCALL(syscall(SYS_pivot_root, "/tmp", "/tmp"));
135:       KJ_SYSCALL(fchdir(oldRootDir));
136:       KJ_SYSCALL(umount2(".", MNT_DETACH));
137:       KJ_SYSCALL(chdir("/tmp"));
138:     }
